**行号：Message.ts L226–L253**

### 代码原文
```ts
// src7/plugins/channels/Message.ts
 226  /** 事件 channel/recall 载荷：渠道确认原消息被撤回后发出。 */
 227  export interface ChannelRecallEvent {
 228    /** 渠道名（feishu / wechat / http / cli）。 */
 229    channel: string;
 230    /** 平台账号 ID（如飞书 appId）。 */
