 242    /** 谁撤回的：由渠道根据可信身份配置与本地聊天日志核定。 */
 243    recalledBy: {
 244      /** 撤回人渠道原始 ID（平台仅返回 message_owner 且本地尚未落盘时为空串）。 */
 245      id: string;
 246      /** 撤回身份类别：sender 原发消息人自撤，owner 本人撤回。 */
 247      kind: 'sender' | 'owner';
