**行号：Reply.ts L77–L114**

### 代码原文
```ts
// src7/plugins/channels/Reply.ts
  77  /** 事件 channel/reply 请求载荷。 */
  78  export interface ChannelReplyRequest {
  79    /** 单次事件往返局部关联 ID。 */
  80    requestId: string;
  81    /** 渠道名（feishu / wechat / http / cli）。 */
  82    channel: string;
  83    /** 当前机器人名。 */
  84    bot: string;
  85    /** 回复请求幂等键。 */
  86    replyRequestKey: string;
  87    /** 回复轮键。 */
  88    replyRoundKey: string;
  89    /** 本轮内序号。 */
  90    replyIndex: number;
  91    /** 回复类别：progress | final。 */
  92    kind: ReplyKind;
  93    /** 发送模式：纯文字或附件。 */
  94    mode: 'text' | 'attachment';
  95    /**
  96     * 不可变来源快照：回某条消息时有。
  97     * 没有来源快照的（自动回话、relay 回信、本人批准的主动发件）一定带 target.address，按地址发。
  98     */
  99    sourceSnapshot?: messageModule.SourceSnapshot;
 100    /** 请求正文摘要，用于同键冲突校验。 */
 101    payloadHash: string;
 102    /** 发送片段列表。 */
 103    parts: ReplyPartInput[];
 104    /** 跨渠道或跨聊天发送目标；未指定别处时为 undefined，沿用 sourceSnapshot。 */
 105    target?: targetModule.ChannelReplyTarget;
 106    /** 哪场会话说的：按地址发的自动回话和 relay 回信带上，渠道照会话定细节（命令行出错标红，微信只发做完的一轮，网页挂回会话认领的那条）。 */
 107    sessionId?: string;
